/**
 * One row of seats in a theatre. Seat 0 is at the aisle.
 * @author Pranjal Patra
 * @version 1.0
 */
public class SeatRow
{
    private boolean[] booked;

    /**
     * Create a row of seats, all free.
     * @param size The number of seats in the row.
     */
    public SeatRow(int size)
    {
        booked = new boolean[size];
    }

    /**
     * Return the number of seats in the row.
     * @return The row's size.
     */
    public int getSize()
    {
        return booked.length;
    }

    /**
     * Say whether a seat is booked.
     * @param seat The seat number, from 0 to the size minus 1.
     * @return true if the seat is booked.
     */
    public boolean isBooked(int seat)
    {
        return booked[seat];
    }

    /**
     * Book a seat, if it exists and is free.
     * @param seat The seat number.
     * @return true if the seat was booked, false if it does not exist
     *         or is already booked.
     */
    public boolean book(int seat)
    {
        if(seat < 0 || seat >= booked.length) {
            return false;
        }
        if(booked[seat]) {
            return false;
        }
        booked[seat] = true;
        return true;
    }

    /**
     * Return the number of free seats.
     * @return How many seats are not booked.
     */
    public int countFree()
    {
        int free = 0;
        for(boolean taken : booked) {
            if(!taken) {
                free++;
            }
        }
        return free;
    }

    /**
     * Return the free seat nearest the aisle.
     * @return The lowest free seat number, or -1 if the row is full.
     */
    public int firstFree()
    {
        for(int seat = 0; seat < booked.length; seat++) {
            if(!booked[seat]) {
                return seat;
            }
        }
        return -1;
    }
}

public class TheatreCheck
{
    public static void main(String[] args)
    {
        Theatre empty = new Theatre(0, 3);
        System.out.println("Empty: " + empty.countBooked());
        System.out.println("Empty book: " + empty.book(0, 0));
        Theatre zero = new Theatre(2, 0);
        System.out.println("Zero seats: " + zero.book(0, 0));
        Theatre t = new Theatre(2, 2);
        System.out.println("Initial: " + t.countBooked());
        System.out.println("First: " + t.book(0, 0));
        System.out.println("Repeat: " + t.book(0, 0));
        System.out.println("Other row: " + t.book(1, 0));
        System.out.println("Bad row: " + t.book(-1, 0));
        System.out.println("Past row: " + t.book(2, 0));
        System.out.println("Bad seat: " + t.book(0, -1));
        System.out.println("Past seat: " + t.book(0, 2));
        System.out.println("Count: " + t.countBooked());
        System.out.println("Count again: " + t.countBooked());
    }
}

